import{_ as t,c as i,o,ae as a}from"./chunks/framework.DCU7Csu6.js";const p=JSON.parse('{"title":"EPIC 48 — SDK Timeout & Configuration DX Improvements","description":"","frontmatter":{},"headers":[],"relativePath":"epics/EPIC_48_TIMEOUT_CONFIG_DX.md","filePath":"epics/EPIC_48_TIMEOUT_CONFIG_DX.md"}'),r={name:"epics/EPIC_48_TIMEOUT_CONFIG_DX.md"};function n(s,e,l,c,d,u){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="epic-48-—-sdk-timeout-configuration-dx-improvements" tabindex="-1">EPIC 48 — SDK Timeout &amp; Configuration DX Improvements <a class="header-anchor" href="#epic-48-—-sdk-timeout-configuration-dx-improvements" aria-label="Permalink to &quot;EPIC 48 — SDK Timeout &amp; Configuration DX Improvements&quot;">​</a></h1><h2 id="epic-goal" tabindex="-1">Epic Goal <a class="header-anchor" href="#epic-goal" aria-label="Permalink to &quot;Epic Goal&quot;">​</a></h2><p>Improve SDK developer experience by adding per-request timeout support, enhancing retry/timeout logging transparency, and ensuring documentation clearly communicates all available configuration options — addressing real user confusion about SDK capabilities.</p><h2 id="epic-description" tabindex="-1">Epic Description <a class="header-anchor" href="#epic-description" aria-label="Permalink to &quot;Epic Description&quot;">​</a></h2><h3 id="background-user-feedback" tabindex="-1">Background &amp; User Feedback <a class="header-anchor" href="#background-user-feedback" aria-label="Permalink to &quot;Background &amp; User Feedback&quot;">​</a></h3><p>Real-world users reported that &quot;WildberriesSDK не предоставляет способа настроить timeout в конструкторе. Параметры только <code>{ apiKey }</code>&quot;. This is factually incorrect — the SDK supports <code>timeout</code>, <code>retryConfig</code>, <code>rateLimitConfig</code>, <code>logLevel</code>, and <code>baseUrls</code>. However, the fact that users don&#39;t know about these options indicates a serious documentation and discoverability gap.</p><p>Additionally, users experience ETIMEDOUT errors on long-running operations (e.g., orders_fbs_sync with large datasets) without understanding that:</p><ol><li>The timeout is configurable</li><li>Retries happen automatically</li><li>The default 30s timeout can be increased</li></ol><h3 id="existing-system-context" tabindex="-1">Existing System Context <a class="header-anchor" href="#existing-system-context" aria-label="Permalink to &quot;Existing System Context&quot;">​</a></h3><ul><li><strong>SDK Config</strong>: <code>SDKConfig</code> interface in <code>src/config/sdk-config.ts</code> — already supports timeout</li><li><strong>Request Options</strong>: <code>RequestOptions</code> interface — missing per-request timeout</li><li><strong>Base Client</strong>: <code>src/client/base-client.ts</code> — axios instance with global timeout only</li><li><strong>Retry Handler</strong>: <code>src/client/retry-handler.ts</code> — retries timeouts but logs minimally</li><li><strong>Error Classes</strong>: <code>NetworkError</code> with <code>isTimeout</code> flag — works correctly</li><li><strong>Documentation</strong>: VitePress site at GitHub Pages, <code>docs/guides/configuration.md</code> exists</li><li><strong>Examples</strong>: 47+ example files in <code>examples/</code></li></ul><h3 id="enhancement-details" tabindex="-1">Enhancement Details <a class="header-anchor" href="#enhancement-details" aria-label="Permalink to &quot;Enhancement Details&quot;">​</a></h3><p>Three stories addressing SDK code, logging, and documentation:</p><ol><li><strong>Per-request timeout override</strong> — Add <code>timeout</code> to <code>RequestOptions</code>, pass to axios per-call</li><li><strong>Retry/timeout logging transparency</strong> — Log retry attempts, timeout warnings, backoff delays</li><li><strong>Configuration documentation overhaul</strong> — README, guides, examples, FAQ updates (EN + RU)</li></ol><h3 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h3><ul><li>Users can set timeout per-request for long-running operations</li><li>Users see informative logs during retry/timeout scenarios</li><li>Documentation clearly shows all configuration options with practical examples</li><li>GitHub Pages updated with new content</li></ul><h2 id="stories" tabindex="-1">Stories <a class="header-anchor" href="#stories" aria-label="Permalink to &quot;Stories&quot;">​</a></h2><h3 id="story-1-per-request-timeout-in-requestoptions" tabindex="-1">Story 1: Per-Request Timeout in RequestOptions <a class="header-anchor" href="#story-1-per-request-timeout-in-requestoptions" aria-label="Permalink to &quot;Story 1: Per-Request Timeout in RequestOptions&quot;">​</a></h3><p><strong>Scope</strong>: SDK code change (backward compatible)</p><ul><li>Add <code>timeout?: number</code> to <code>RequestOptions</code> interface</li><li>Update <code>BaseClient.get/post/put/patch/delete</code> to pass per-request timeout to axios config</li><li>Per-request timeout overrides global <code>SDKConfig.timeout</code></li><li>Update unit tests for BaseClient</li><li>Update type exports</li></ul><h3 id="story-2-retry-timeout-logging-transparency" tabindex="-1">Story 2: Retry &amp; Timeout Logging Transparency <a class="header-anchor" href="#story-2-retry-timeout-logging-transparency" aria-label="Permalink to &quot;Story 2: Retry &amp; Timeout Logging Transparency&quot;">​</a></h3><p><strong>Scope</strong>: SDK code change (backward compatible)</p><ul><li>Add <code>info</code>-level log on each retry attempt: &quot;Retry {n}/{max} for {url} after {delay}ms&quot;</li><li>Add <code>warn</code>-level log on timeout: &quot;Request to {url} timed out after {timeout}ms&quot;</li><li>Add <code>debug</code>-level log with full retry context (error details, attempt history)</li><li>Respect existing <code>logLevel</code> configuration</li><li>Update retry-handler and base-client logging</li></ul><h3 id="story-3-configuration-documentation-examples" tabindex="-1">Story 3: Configuration Documentation &amp; Examples <a class="header-anchor" href="#story-3-configuration-documentation-examples" aria-label="Permalink to &quot;Story 3: Configuration Documentation &amp; Examples&quot;">​</a></h3><p><strong>Scope</strong>: Documentation + GitHub Pages</p><ul><li>Update <code>docs/guides/configuration.md</code> with comprehensive timeout/retry examples</li><li>Update <code>README.md</code> quickstart with configuration beyond <code>{ apiKey }</code></li><li>Create <code>examples/custom-timeout-configuration.ts</code> example</li><li>Add timeout FAQ entries to <code>FAQ.md</code></li><li>Update Russian docs (<code>docs/ru/guides/configuration.md</code>)</li><li>Ensure GitHub Pages deployment includes all changes</li></ul><h2 id="compatibility-requirements" tabindex="-1">Compatibility Requirements <a class="header-anchor" href="#compatibility-requirements" aria-label="Permalink to &quot;Compatibility Requirements&quot;">​</a></h2><ul><li>[x] Existing APIs unchanged (all changes are additive)</li><li>[x] No DB changes</li><li>[x] RequestOptions changes backward compatible (new optional field)</li><li>[x] No breaking changes to any module</li><li>[x] Existing tests continue to pass</li></ul><h2 id="risk-mitigation" tabindex="-1">Risk Mitigation <a class="header-anchor" href="#risk-mitigation" aria-label="Permalink to &quot;Risk Mitigation&quot;">​</a></h2><ul><li><strong>Primary Risk</strong>: Per-request timeout may interact unexpectedly with retry handler</li><li><strong>Mitigation</strong>: Per-request timeout applies to each individual attempt, not total retry time</li><li><strong>Rollback Plan</strong>: Revert optional <code>timeout</code> field — no breaking change</li></ul><h2 id="definition-of-done" tabindex="-1">Definition of Done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of Done&quot;">​</a></h2><ul><li>[ ] All 3 stories completed with AC met</li><li>[ ] Existing functionality verified (all tests pass)</li><li>[ ] GitHub Pages deployed with updated docs</li><li>[ ] No regressions in any module</li><li>[ ] CHANGELOG updated for v3.2.0</li></ul>',31)])])}const g=t(r,[["render",n]]);export{p as __pageData,g as default};
